const dvDate = $json.dvDate;
const putAwayDate = $json.putAwayDate;
const financialStatus = ($json.financialStatus || '').toLowerCase();
const poAmount = parseFloat($json.poAmount) || 0;
const billAmount = parseFloat($json.billAmount) || 0;

// Calculate Delivery Status
let deliveryStatus = '';

if (putAwayDate && putAwayDate !== '') {
  deliveryStatus = 'Available For Sale';
} else if (dvDate && dvDate !== '') {
  deliveryStatus = 'Received';
} else if (financialStatus === 'authorised') {
  deliveryStatus = 'Goods in Transit';
} else {
  deliveryStatus = 'Ordered';
}

// Calculate Amount Variance
let amountVariance = null;
if (poAmount && billAmount) {
  amountVariance = Math.round((poAmount - billAmount) * 100) / 100;
}

return [{
  json: {
    recordId: $json.recordId,
    deliveryStatus,
    amountVariance,
    poAmount,
    billAmount,
    dvDate,
    putAwayDate,
    financialStatus
  }
}];

